function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 100) return 'mat needs 1 to 100 rows.';
  const n = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (n < 1 || n > 100) return 'Each row needs 1 to 100 cells.';
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Every cell must be 0 or 1.';
  }
  return null;
}

