function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const m = large ? int(60, 100) : int(1, 5);
  const n = large ? int(60, 100) : int(1, 5);
  // Sparse matrices have many special cells; denser ones have few or none.
  const density = large ? [0.002, 0.006, 0.02, 0.3][int(0, 3)] : rand() * 0.7;
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  return [mat];
}
